@triton.jit
def _abs_nd_kernel(
    x_ptr,
    n,
    s0,
    s1,
    s2,
    s3,
    s4,
    s5,
    t0,
    t1,
    t2,
    t3,
    t4,
    t5,
    RANK: tl.constexpr,
    BLOCK: tl.constexpr,
    STEPS: tl.constexpr,
):
    """``x_ptr`` is written at its own logical offsets: dims are innermost-first."""
    base = tl.program_id(0) * (BLOCK * STEPS)
    for s in tl.static_range(STEPS):
        idx = base + s * BLOCK + tl.arange(0, BLOCK)
        m = idx < n
        rem = idx
        off = idx * 0
        if RANK > 0:
            off += (rem % s0) * t0
            rem = rem // s0
        if RANK > 1:
            off += (rem % s1) * t1
            rem = rem // s1
        if RANK > 2:
            off += (rem % s2) * t2
            rem = rem // s2
        if RANK > 3:
            off += (rem % s3) * t3
            rem = rem // s3
        if RANK > 4:
            off += (rem % s4) * t4
            rem = rem // s4
        if RANK > 5:
            off += (rem % s5) * t5
        x = tl.load(x_ptr + off, mask=m)
        tl.store(x_ptr + off, tl.abs(x), mask=m)


def _block_for(n, esize):
    """Elements per tile, aimed at ~8-16 KB of live data per program."""
    if n <= 4096:
        return 1024
    if n <= 65536:
        return 2048
    return 4096 if esize >= 4 else 8192


def _steps_for(n, block, esize):
    """Tiles per program: keep the grid legal and give it ~64 KB of work."""
    tiles = -(-n // block)
    steps = 1
    while -(-tiles // steps) > _MAX_GRID:
        steps *= 2
    while steps * block * esize < _MIN_PROGRAM_BYTES and steps < tiles:
        steps *= 2
    return steps


def _collapse(t):
    """Minimal (size, stride) form, innermost first.

    Adjacent dims whose strides chain (``st == prev_size * prev_stride``) are
    merged, so a contiguous tensor collapses to ``[(numel, 1)]`` and a merely
    permuted dense view does too.  Raises when the view provably aliases one
    address from several logical elements, which is what ATen refuses in place.
    """
    shape = t.shape
    stride = t.stride()
    dims = []
    for sz, st in zip(shape, stride):
        if sz > 1 and st == 0:
            raise RuntimeError(
                "unsupported operation: more than one element of the written-to "
                "tensor refers to a single memory location. Please clone() the "
                "tensor before performing the operation."
            )
        if sz != 1:
            dims.append((sz, st))
    if not dims:
        return [(1, 1)]
    dims = sorted(dims, key=lambda p: p[1])
    out = []
    for sz, st in dims:
        if out and st == out[-1][0] * out[-1][1]:
            out[-1] = (out[-1][0] * sz, out[-1][1])
        else:
            out.append([sz, st])
    return out


def _abs_flat(t):
    n = t.numel()
    esize = t.element_size()
    block = _block_for(n, esize)
    steps = _steps_for(n, block, esize)
    _abs_flat_kernel[(-(-n // (block * steps)),)](t, n, block, steps)


def _abs_strided(t, dims):
    n = t.numel()
    esize = t.element_size()
    block = _block_for(n, esize)
    steps = _steps_for(n, block, esize)
    if len(dims) > _MAX_DIMS:
        raise RuntimeError("foreach_abs_: unsupported view rank")
    sizes = [d[0] for d in dims]
    step = [d[1] for d in dims]
    while len(sizes) < _MAX_DIMS:
        sizes.append(1)
        step.append(0)
    _abs_nd_kernel[(-(-n // (block * steps)),)](
        t,
        n,
        sizes[0],
        sizes[1],
        sizes[2],
        sizes[3],
        sizes[4],
        sizes[5],
        step[0],
        step[1],
        step[2],
        step[3],
        step[4],
        step[5],
        len(dims),
        block,
        steps,
    )


def _abs_group(group):
    """One dispatch for a same-dtype list of dense tensors when that pays off."""
    k = len(group)
    if k == 1:
        _abs_flat(group[0])
        return
    ns = [t.numel() for t in group]
    max_n = max(ns)
    min_n = min(ns)
    if max_n > 2 * min_n:
        # Too skewed: a shared tile axis would launch mostly idle programs.
        for t in group:
            _abs_flat(t)
        return
    esize = group[0].element_size()
    block = _block_for(max_n, esize)
    steps = _steps_for(max_n, block, esize)
    tiles = -(-max_n // (block * steps))
    pad = _NT - k
    ptrs = group + [group[0]] * pad
    args = ns + [0] * pad
    _abs_fused16_kernel[(tiles, k)](*ptrs, *args, block, steps)


def foreach_abs_(self, *extra):
    tensors = (self,) + extra if extra else self
    if isinstance(tensors, torch.Tensor):
        tensors = (tensors,)
    if not isinstance(tensors, (list, tuple)):
        raise TypeError("argument 'self' must be tuple of Tensors")
    if len(tensors) == 0:
        raise RuntimeError("Tensor list must have at least one tensor.")

    groups = {}
    for t in tensors:
        dtype = t.dtype
        if dtype.is_complex:
            raise RuntimeError("In-place abs is not supported for complex tensors.")
        if not dtype.is_signed:
            # bool and unsigned integers: |x| == x, nothing to write.
            continue
        n = t.numel()
        if n == 0:
            continue
        if t.is_contiguous():
            bucket = groups.get(dtype)
            if bucket is None:
                groups[dtype] = [t]
            else:
                bucket.append(t)
            continue
        dims = _collapse(t)
        if len(dims) == 1 and dims[0][1] == 1:
            bucket = groups.get(dtype)
            if bucket is None:
                groups[dtype] = [t]
            else:
                bucket.append(t)
        else:
            _abs_strided(t, dims)

    for group in groups.values():
        if len(group) <= _NT:
            _abs_group(group)
        else:
            for i in range(0, len(group), _NT):
                _abs_group(group[i : i + _NT])
    return None
